impl RetryConfig {
    /// Delay in milliseconds to wait before the `retry`-th retry (0-based).
    ///
    /// The delay grows exponentially from `base_delay_ms`:
    /// `min(base_delay_ms * 2^retry, max_delay_ms)`. The exponent is capped
    /// and all arithmetic is saturating, so very large retry counts never
    /// overflow and simply saturate at [`RetryConfig::max_delay_ms`].
    pub fn retry_delay_ms(&self, retry: u32) -> u64 {
        // Cap the exponent so `1u64 << exponent` can never overflow.
        let exponent = retry.min(63);
        let doubled = self.base_delay_ms.saturating_mul(1u64 << exponent);
        doubled.min(self.max_delay_ms)
    }
}

