//! End-to-end coverage of the public retry policy API.

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError, Sleeper};

fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms,
        max_delay_ms,
    }
}

fn transient(msg: &str) -> RetryError {
    RetryError::Transient(msg.to_string())
}

#[test]
fn retries_transient_failures_until_success() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(5, 25, 1000), &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(transient("flaky"))
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![25, 50, 100]);
}

#[test]
fn permanent_error_returns_immediately() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(10, 25, 1000), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("bad request".into()))
    });
    assert_eq!(result, Err(RetryError::Permanent("bad request".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn backoff_saturates_at_max_delay_and_never_overflows() {
    // A huge base delay with many retries: every recorded delay must be
    // exactly `max_delay_ms`, and the run must complete without panicking.
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(10, u64::MAX, 500), &mut sleeper, || {
        calls += 1;
        Err(transient("flaky"))
    });
    assert_eq!(result, Err(transient("flaky")));
    assert_eq!(calls, 10);
    assert_eq!(sleeper.sleeps, vec![500; 9]);
}

#[test]
fn max_attempts_includes_the_first_call() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(2, 25, 1000), &mut sleeper, || {
        calls += 1;
        Err(transient("flaky"))
    });
    assert_eq!(result, Err(transient("flaky")));
    assert_eq!(calls, 2);
    assert_eq!(sleeper.sleeps, vec![25]);
}

#[test]
fn works_with_custom_sleeper() {
    struct RecordingSleeper {
        total: u64,
    }
    impl Sleeper for RecordingSleeper {
        fn sleep_ms(&mut self, ms: u64) {
            self.total += ms;
        }
    }

    let mut sleeper = RecordingSleeper { total: 0 };
    let mut calls = 0;
    let result = run_job(&config(4, 10, 1000), &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(transient("flaky"))
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.total, 10 + 20 + 40);
}

